            [5723] = "Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno.",
            [5724] = "Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno.",
            [5725] = "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas.",
            [5726] = "Lleva una insignia de General a Thrall a Orgrimmar.",
            [5727] = "Lleva la insignia de General a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar.",
            [5728] = "Mata a Bazzalan y a Jergosh el Invocador y ve a ver a Thrall a Orgrimmar.",
            [5729] = "Habla con Neeru Hojafuego en Orgrimmar.",
            [5730] = "Habla con Thrall en Orgrimmar y cuéntale lo que has averiguado.",
            [5761] = "Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar.",
            [6521] = "Lleva la cabeza del embajador Malcin a Varimathras, que está en Entrañas.",
            [6522] = "Lleva el pergamino a Varimathras, que está en Entrañas.",
            [6561] = "Llévale la cabeza del Señor Crepuscular Kelris a Bashana Runatótem en Cima del Trueno.",
            [6562] = "Habla con Je'neu Sancrea en Vallefresno.",
            [6563] = "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno.",
            [6564] = "Llévale la nota humedecida a Je'neu Sancrea en Vallefresno.",
            [6565] = "Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve junto a Je'neu Sancrea en Vallefresno.",
            [6626] = "Mata a 8 guardias de batalla y 8 tejespinas Rajacieno y 8 adeptos Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno.",
            [6627] = "Responde la pregunta de Braug Espiritoscuro con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés lista.",
            [6628] = "Responde la pregunta de Parqual Fintallas con acierto y después habla con él de nuevo. Se quedará en Entrañas hasta que estés lista.",
            [6921] = "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.",
            [92401] = "Investiga la desaparición de Edward Tejecorazón en las Ruinas de Lordaeron.",
            [92415] = "Lleva la carta manchada de sangre a la supervisora de huérfanos Ruiseñor en la Ciudad de Ventormenta.",
            [92421] = "Consigue 25 extremidades intactas en las Ruinas de Lordaeron y llévaselas a Morbin Penívea en Entrañas.",
            [92422] = "Mata a Rath'mael en las Ruinas de Lordaeron por encargo del guardia de la Muerte Kristof, que espera en Rémol.",
            [92742] = "Usa el equipo de muestras de agua de pozo para conseguir muestras de los pozos de la Finca de Jansen y la Granja de Molsen.",
            [92744] = "Alba Lunajusta quiere que consigas 7 branquias de múrloc de Playa Larga por la cosa de los Páramos de Poniente.",
            [92745] = "Acaba con 4 cavadores kóbolds en la Mina de Jango y con 6 mineros Zarparrío en la Mina de la Costa del Oro.",
            [92747] = "Consigue 8 suministros industriales sospechosos en Arroyo de la Luna.",
            [92748] = "Viaja al Distrito de los Enanos de Ventormenta y busca a algún ingeniero que pueda ayudarte.",
            [92749] = "Consigue 10 de dinamita burda mediante fabricación, comercio o en la casa de subastas y luego vuelve con Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta.",
            [92750] = "Habla con alguien del servicio secreto de Ventormenta para conseguir un detonador a distancia.",
            [92751] = "Llévale el equipo de detonador a distancia a Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta.",
            [92752] = "Vuelve con Alba Lunajusta en los Páramos de Poniente.",
            [92753] = "Encuentra la forja oculta en las Minas de la Muerte y coloca los explosivos extradestructivos cerca. Luego, reúnete con Alba Lunajusta en la salida de las minas.",
            [92819] = "Utiliza el detonador.",
            [95161] = "Entrega la carta manchada de sangre a Avette Bosquevil en el Bosque del Ocaso.",
            [95189] = "Devuelve el blasón de Lordaeron a lady Dena Kennedy en la Ciudad de Ventormenta.",
            [95195] = "Consigue 10 insignias ensangrentadas y llévaselas al general Marcus Jonathan en la Ciudad de Ventormenta.",
            [95204] = "Lleva el blasón de Lordaeron a Oran Contorpiente en Entrañas.",
            [95216] = "Consigue la cepa muy tóxica de Colmimarchito en las Ruinas de Lordaeron y llévasela a Theodore Griffs en Entrañas.",
            [95250] = "Consigue la cabeza del barón en las Ruinas de Lordaeron y llévasela al capitán Truman.",
            [95646] = "Mata a un horror de las Tierras Altas en una excavación y lleva su núcleo a Rethiel el Guardaverde en Los Humedales.",
            [95647] = "Encuentra a Ardin Pastal en la excavación.",
            [95663] = "Viaja a Los Humedales y reúnete con la agente de los Mortacechadores en las colinas sobre el campamento Faucedraco.",
            [95664] = "Lleva la reliquia titánica al Alto de los Ancestros, en Cima del Trueno, y busca a alguien que pueda contarte más acerca de ella.",
            [95682] = "Mata a las fuerzas de los Faucedraco en las excavaciones y vuelve con la agente de los Mortacechadores fuera con lo que hayas recuperado.",
            [95697] = "Entra en la excavación de Los Humedales y consigue carne de raptor de la espesura.",
            [95737] = "Habla con Caitlin Pastal en el Puerto de Menethil.",
            [95772] = "Busca a Daewyn, el hermano de Dorin Filosón, en la Excavación de Whelgar.",
            [95795] = "Vuelve con Dorin Filosón.",
            [95809] = "Vuelve con Caitlin Pastal en el Puerto de Menethil.",
            [95810] = "Llévale la reliquia titánica al prospector Whelgar, que está en su excavación de Los Humedales.",
            [96391] = "Entrega el mapa Hierro Negro al videnterra Farsen en Dun Morogh.",
            [96393] = "Entra en el Salón de los Feudales bajo Antigua Forjaz y hazte con la cabeza de Durgen Martillo Funesto.",
            [96394] = "Mata a 15 apariciones iracundas y 10 almas atormentadas, antes de acabar con el espíritu de Yunquemar.",
            [96395] = "Devuelve el espíritu de Faldrim Yunquemar a su descanso eterno y luego vuelve con el auxiliar fantasmal en el Salón de los Feudales.",
            [96403] = "Recupera 8 reliquias enanas en el Salón de los Feudales.",
            [97288] = "Entrega la cabeza abominable al maestro boticario Faranell en Entrañas.",
            [97289] = "Lleva la cabeza del barón junto al cuerpo de Othmar en Entrañas.",
            [97290] = "Informa de tus hallazgos al maestro boticario Faranell de Entrañas.",
            [97291] = "Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a los instructores de herboristería para reunir hierba ampolla y a la vendedora de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas.",
            [97292] = "Inyecta el suero siseante en el sistema que hay sobre el cuerpo de Othmar para el maestro boticario Faranell.",
            [98423] = "Entrega el tratado de entendimiento a Magni Barbabronce en Forjaz.",
            [98815] = "Devuelve 4 pellejos de raptor de matorral a James Halloran, el peletero, en Puerto de Menethil.",
            [98823] = "Entrega la reliquia titánica a Muln Furiatierra, que está en la Meseta de Miracielos de Mulgore.",
            [98824] = "Entrega la reliquia titánica al alto expedicionario Magellas, que está en la Sala de los Expedicionarios de Forjaz.",
        },
