        desc = {
            ALCAZ = "Isla de Alcaz: una prisión donde la Hermandad Defias retenía a nobles para pedir rescate, ahora asediada por los nagas.",
            BARROW = "Una vasta red de túmulos de los elfos de la noche que encierra a los presos más peligrosos del mundo, y la corrupción se extiende.",
            BFD = "La Ensenada de Zoram: un templo inundado de los elfos de la noche, ahora en manos de nagas, sátiros y sectarios al servicio de Aku'mai.",
            BLACKMAW = "Azshara, norte: una gran ciudad fúrbolg que lucha contra su propia corrupción. Sus túneles llegan hasta Cavernas del Túmulo.",
            BRD = "Montaña Roca Negra: bajo la montaña se extiende la capital fundida de los Enanos de Hierro Negro, gobernada por Emperador Dagran Thaurissan.",
            DAL = "La barrera del Kirin Tor se debilita y la ciudad violeta está invadida por encantamientos desatados, ensamblajes arcanos y fugas de energía demoníaca.",
            DM = "Bajo las minas abandonadas de Arroyo de la Luna, la Hermandad Defias construye un gigantesco navío para atacar Ciudad de Ventormenta. Su líder: Edwin VanCleef.",
            DME = "Los jardines orientales cubiertos de maleza de una antigua ciudad élfica, donde Alzzin el Formaferal corrompe los árboles ancestrales.",
            DMN = "Los ogros se han adueñado de los patios del norte de una antigua ciudad élfica. Su jefe: Rey Gordok. Derrótalo y reclama su tributo.",
            DMW = "En el ala oeste, los Altonato drenan al demonio Immol'thar, a las órdenes de Príncipe Tortheldrin.",
            DROWNED = "Vega de Tuercespina: unas ruinas trol sumergidas han emergido del mar frente a la costa, y troles, nagas y piratas se disputan lo que encierran.",
            EXC = "Una excavación de la Liga de Expedicionarios abrió antiguas salas de los titanes: niebla extraña, destellos de luz y ensamblajes que aún montan guardia.",
            GNOMER = "La capital irradiada de los gnomos, perdida ante los troggs y la traición de Mekigeniero Termochufe.",
            HOT = "Forjaz: bajo la vieja ciudad, intrusos de los Enanos de Hierro Negro han entrado en las tumbas reales de los antiguos thanes, y los muertos sin descanso han despertado.",
            HYJAL = "Monte Hyjal: algo drena el poder de las tierras de alrededor, donde aún vagan los fantasmas de una antigua guerra.",
            KROLDOK = "Una enorme fortaleza ogra cuyos asaltantes toman prisioneros, y cuyos cánticos nocturnos delatan un vínculo con sectarios.",
            LBRS = "Las salas inferiores de una fortaleza de orcos y ogros, a las órdenes de Señor supremo Vermiothalak. Diez jugadores en Forever.",
            MARA = "Desolace: una caverna sagrada de los centauros, corrompida por la elemental de tierra Princesa Theradras.",
            ONY = "Onyxia, hija del gran dragón negro, espera en su guarida (Marjal Revolcafango). Se desbloquea con la primera fase de bandas de Forever.",
            RFC = "Orgrimmar: en las cavernas volcánicas bajo la ciudad, troggs y sectarios (Filo Ardiente) conspiran en la sombra, y la Horda está amenazada.",
            RFD = "Los antiguos túmulos funerarios de los jabaespín han caído en manos de la Plaga, liderada por el exánime Amnennar el Gélido.",
            RFK = "Los Baldíos, sur: un laberinto espinoso, hogar de los jabaespín y de su sacerdotisa Charlga Filonavaja.",
            ROL = "La Plaga aún domina la capital en ruinas sobre Entrañas, donde un nigromante acumula poder entre las cenizas.",
            SCHOLO = "Castel Darrow: en las criptas bajo el castillo, unos sectarios han fundado una escuela de nigromancia dirigida por Maestro oscuro Gandling.",
            SFK = "Bosque de Argénteos: Archimago Arugal y sus huargen dominan la fortaleza, y su maldición se extiende cada vez más.",
            SHAPER = "Cráter de Un'Goro: entre las colinas se alza una instalación intacta de los titanes, vibrante de cristales de poder y de una energía inexplicable.",
            SMARM = "El arsenal de la orden (Cruzada Escarlata) está custodiado por su campeón, Herod.",
            SMCATH = "En el corazón del monasterio, Comandante Escarlata Mograine y Alta inquisidora Melenablanca dirigen a los fanáticos.",
            SMGY = "Cruzados sin descanso rondan el cementerio del monasterio, donde aún merodea Mago sangriento Thalnos.",
            SMLIB = "Domador de jaurías Loksey y Arcanista Doan guardan los tomos prohibidos de la orden (Cruzada Escarlata).",
            ST = "El templo sumergido donde los sacerdotes trols intentan invocar al dios de la sangre. Su encarnación: Avatar de Hakkar.",
            STOCKS = "La prisión de Ciudad de Ventormenta se ha sumido en el caos: reclusos de la Hermandad Defias se han hecho con los bloques de celdas, liderados por Bazil Thredd.",
            STRATLIVE = "Stratholme: la Cruzada Escarlata defiende de la Plaga las calles en llamas tras la puerta principal.",
            STRATUD = "Stratholme: Barón Osahendido gobierna la mitad de la ciudad en manos de la Plaga, tras la entrada de servicio.",
            UBRS = "La cima de la fortaleza, donde Jefe de Guerra Desgarro Puño Negro y General Drakkisath dirigen las fuerzas del Vuelo Negro. Diez jugadores en Forever.",
            ULDA = "Tierras Inhóspitas: una antigua cámara de los titanes, disputada por los Enanos de Hierro Negro, los troggs y el guardián de piedra Archaedas.",
            WC = "Los Baldíos: en las profundidades, druidas renegados velan a un druida dormido cuya pesadilla ha corrompido las cavernas y todo lo que hay en ellas.",
            ZF = "Tanaris: una ciudad trol abrasada por el sol, gobernada por Jefe Ukorz Cabellarena.",
        },
