            ["Try on"] = "Probar",
            ["Try on set (Dressing Room)"] = "Probar conjunto (probador)",
            ["Try the name of a dungeon, boss, quest, zone, mob or item. Parts of words work too, e.g. \"vanc\" or \"blade\"."] = "Prueba con el nombre de una mazmorra, jefe, misión, zona, criatura u objeto. También valen partes de palabras, p. ej. «vanc» u «hoja».",
            ["Turbo"] = "Turbo",
            ["Turbo: %d ms per frame, the sim is done soonest, the game can run slower meanwhile."] = "Turbo: %d ms por fotograma, la simulación termina lo antes posible, mientras tanto el juego puede ir más lento.",
            ["Turn in"] = "Entregar",
            ["Two sets of your own: click a slot to pick any item your character can put on there, or drop an item from your bags on it. The set fights on its own."] = "Dos conjuntos propios: haz clic en una ranura para elegir cualquier objeto que tu personaje pueda ponerse ahí, o suelta en ella un objeto de tus bolsas. El conjunto combate por sí solo.",
            ["Two-Hand"] = "Dos manos",
            ["Two-hand weapon"] = "Arma de dos manos",
            ["Two-hander in the main hand"] = "Arma de dos manos en la mano principal",
            ["Type"] = "Tipo",
            ["Type /lf collect stop to cancel. Please stay logged in."] = "Escribe /lf collect stop para cancelar. Por favor, no cierres sesión.",
            ["Type /reload, then send the file WTF\\Account\\<account>\\SavedVariables\\Lootified.lua."] = "Escribe /reload y envía el archivo WTF\\Account\\<cuenta>\\SavedVariables\\Lootified.lua.",
            ["Type a name, a slot or a place: the list follows as you type. The switch beside it and Sort change what shows and in which order."] = "Escribe un nombre, una ranura o un lugar: la lista se actualiza mientras escribes. El interruptor de al lado y Orden cambian qué se muestra y en qué orden.",
            ["Type at least 3 letters"] = "Escribe al menos 3 letras",
